from itertools import combinations

def max_melodies_notes(n, notes):
    max_length = -1
    best_combinations = []

    for i in range(1, n+1):
        # Generate all combinations of i notes
        all_combinations = list(combinations(enumerate(notes), i))

        for combination in all_combinations:
            subsequence = [notes[i] for i in combination]
            if is_valid_subsequence(subsequence):
                left = right = 0
                for i in range(1, len(subsequence)):
                    if abs(subsequence[i] - subsequence[i-1]) == 1 or (subsequence[i] % 7 == subsequence[i-1] % 7):
                        left += 1
                    else:
                        right += 1
                max_length = max(max_length, left + right)
                best_combinations.append((left + right, combination))

    return max_length, best_combinations

def is_valid_subsequence(subsequence):
    i, j = 0, 1
    while j < len(subsequence):
        if abs(subsequence[i] - subsequence[j]) == 1 or (subsequence[i] % 7 == subsequence[j] % 7):
            i, j = j, j + 1
        else:
            i += 1
    return i == j and len(subsequence) == j

