import sys

def calculate_goodness(n, q, initial_money, recommendations, probabilities):
    dp = [float("-inf")] * (n + 1)
    dp[0] = 0  # Money for the initial empty segment

    for i in range(n + 1):
        dp[i] = max(dp[i], 0)  # Zero money for the worst case

    for recommendation, probability in recommendations:
        for j in range(recommendation[0], recommendation[1] + 1):
