def div2op2(n, m):
    if n == 0:
        return m
    if n & 1:
        return div2op2(div2(n - 1), m) << 1 ^ m
    return div2op2(div2(n >> 1), m) ^ div2(n >> 1)

def sol(n):
    def solve(i, j, need):
        if need == 0 and i < j:
            return need, [0] + [i] * (2 ** j - 1)
        if i >= n or j == 1:
            return 0, [need, -(2 ** j) - 1]
        c, a = solve(i + 1, j, 0)
        sol2, aa = solve(i + 1, j - 1, -1)
        S = sol2 + a
        return 0, [S] + [i] * (2 ** j - 1) if S >= 0 else [need, -(2 ** j) - 1]
