        if len(graph[u]) not in [2, 3]: continue

        total_removed_added_ways = 0
        for removed in range(3, len(graph[u])):
            if len(graph[u]) not in [2, removed]: 
                continue
            for added in range(1, len(graph[u])):
                if added == removed or len(graph[u]) is not 4 and added == 2: 
                    continue
                if all(i in graph[v] for v in graph[u]): 
                    total_removed_added_ways += graph[u].count(added)

        result += total_removed_added_ways

    return result

