from math import gcd
from typing import List

def find_fair_set(n: int, k: int, nums: List[int]) -> List[int]:
    d = {}
    for i in range(1, n + 1):
        factors = set([gcd(a, i) for a in nums])
        for factor in factors:
            if factor in d and abs(len(d[factor]) - len(factors) + 1) > 1:
                d[factor].append(i)
    fair_set = []
    for factor, indices in d.items():
        if len(factors) == len(indices):
            for i in indices:
                fair_set.append(i)
                if len(fair_set) == k:
                    return fair_set
    return [sorted(fair_set)]

