    dp[0] = 0
    for i in range(2, N + 1):
        dp[i] = dp[i-1]
        L, r = i, i
        counts = [0]
        range_sum = 0
        for j, n in enumerate(A, start=1):
            if j == l:
                if counts[-1] % 2 == 1:
                    range_sum += n
            r += 1
            if j == r:
                counts.append(0)
            if j == r and n == j:
                counts[-1] += 1
            if j == r and n > j:
                counts.append(n-j)
        counts = sorted(counts)
        if j != r and counts[-1] % 2 == 0:
            range_sum -= (j - 1) * (j - 1 - counts[-1]) // (j - 1)
        if j != r and counts[0] > 1:
            range_sum -= (j - 1) * (j - counts[0] + 1) // (j - 1)
        new_changes = count_subarrays(counts)
        dp[i] = min(dp[i], dp[i-2] - new_changes + range_sum)
