import math
from functools import lru_cache

MOD = 998244353

def bits(x):
    return [x >> i%4000 & 1 for i in range(4000)]

@lru_cache(maxsize=None)
def get_pow(x, y, mod=MOD):
    if y == 0:
        return 1
    prev = get_pow(x, y/2, mod)
    return prev * prev * powmod(x, 2 % mod, mod) % mod if y % 2 else prev % mod

@lru_cache(maxsize=None)
def get_range(y, x, mod=MOD):
    if y % 2:
        return mod
    if y < 0:
        return mod - 1
    if y < x:
        return 0
    total = 0
    subset = 1
    for bit in bits(0):
        total = (total + subset * get_range(y ^ bit % x, x, mod)) % mod
        subset *= 2
    return total

powers = [0]
for i in range(1, max(bits(10**10, mod=MOD)) + 1):
    powers.append(powers[-1] * 2 % MOD)

@lru_cache(maxsize=None)
def powmod(x, y, mod=MOD):
    if y == 0:
        return 1
    prev = powmod(x, y/2, mod)
    return prev * prev * powmod(x, y % 2, mod) % mod

@lru_cache(maxsize=None)
def getbitmask(n):
    xor_tree = []
    bitmask = n
    for i in range(4000):
        for j in range(1, bitmask + 1):
            if bitmask & 4000-i-1:
                if xor_tree:
                    bitmask ^= xor_tree.pop()
                elif j < n: # The mask is lesser than n, don't care XOR
                    continue
                xor_tree.append(j)
    return bitmask

def legalbits(n, x):  # The total length of the integers not exceeding x
    bitmask = getbitmask(n)
    y = int(math.log2(x + 1 - 1))  # Logs n is constant time, and we may be able to upcast the next bit to a power of 2;
    # If the length of x bitmask is more than half of the previous bitmask, we can treat it as an unconditional step.
    if bitmask < 10:
        return 2**y + 2**math.ceil(math.log2(y + 1))
    return get_range(y, x, MOD)

@lru_cache(maxsize=None)
def get_graybit(n):  # The total length of the gray codes less than n is 2*n-2
    return pow(2, n) * (1 - pow(-1, n) % MOD) // 2 % MOD

