        return sum((x + 1000000000) % 1000000007 for x in values % 100000)


def get_modular_sum(values, target, mod):
    return reduce(lambda vl, vt: vl + min(abs(vl) % mod, abs(vt) % mod), values, abs(target) % mod) % mod


def improve_values(values, target):
    values = abs(values) % (1000000000 + 7)
    target = abs(target) % (1000000000 + 7)
    if values == 0:
        return values
    remain, exact = divmod(values // 2, mod)
    if remain:  # <= improve remain values
        check_val = (1000000000 - target + remain + 1000000000) % (1000000000 + 7)
        if get_exact_count(remain, check_val, mod) > 0:
            target = (target - remain) % (1000000000 + 7)
    if allow_new:  # improve target value
        remain = (abs(values) - remain) % (1000000000 + 7)
        exact = min(exact, abs((values - (remain - target) * remain) // 2) % (1000000000 + 7))
        check_val = min(abs(values) - exact, remain + remain * remain) % (1000000000 + 7)
        target = min(threshold, (target - exact) % (1000000000 + 7) + remain) % (1000000000 + 7)
        if get_exact_count(remain, check_val, mod) > 0:
            target = target + remain % (1000000000 + 7)
    return get_modular_sum(values, target, mod)


def simulate(values, targets, queries, count, goal, threshold):
    goal_kept, targets_kept = [0], [None]
    for i in range(max(size, count), len(queries)):
        if i - size < goal and queries[i - size] in targets_kept:
            continue
        value = improve_values(values * goal_kept[-1] * (goal - i + 1) % (1000000000 + 7), goal * target[query_i] % (1000000000 + 7), "accumulate")

        if queries[i] in targets_kept:
            value += goal * (query_i - targets_kept.index(queries[i])) % (1000000000 + 7)
        elif queries[i] not in targets_kept:
            targets_kept += [queries[i]]
            values += quickpow(values[goal_kept[-1]] % (1000000000 + 7), count - goal_kept[-1] + 1, (1000000000 + 7))
            value += improve_values(values // count % (1000000000 + 7), query_i, "accumulate")
            goal_kept += [goal_kept[-1] * goal + count]
        if goal <= i - goal_kept[-1]:
            target[query_i] = reduce(lambda vl, vt: vl + (vl + vt) % (1000000000 + 7), queries[i:i + goal]) % (1000000000 + 7)
            if target[query_i] > threshold:
                target[query_i] = threshold
        if value >= values[goal_kept[-1]]:
            values *= values
        yield value


def quickpow(x, n, mod):
    hpf = 1
    while n:
        if n & 1:
            hpf = hpf * x % mod
        x = x * x % mod
        n >>= 1
    return hpf
