    ways = 0
    for root in graph:
        buffer = [root]
        while True:
            prev_buffer = buffer[:]
            buffer = set()
            for neighbor in graph[root]:
                if neighbor not in buffer:
                    buffer.add(neighbor)
                    dfs(graph, neighbor, [])
            if len(buffer) == len(graph) - 1:
                ways += len(buffer) * len(graph) * len(prev_buffer) - len(buffer)
    return ways // 2

