def max_four_melodies(n, notes):
    dp = [0] * (n + 1)
    dp_limit = int(n / 4 + 1)
    max_sum = 0
    for i in range(n - 1, -1, -1):
        new_sum = 0
        for j in range(1, min(4, n - i) + 1):
            current_max = 0
            for curr_l in range(i + 1, n + 1):
                if current_max < curr_l - 1:
                    for strip_len in range(1, 25 + 1):
                        mod_val = (curr_l - strip_len) % 7
                        if notes[i:i + strip_len] == [mod_val + 7 * k for k in range(strip_len)]:
                            current_max = max(current_max, strip_len)
            new_sum += max_sum - dp[j - 1] + current_max
            dp[j - 1] = max(dp[j - 1], new_sum)
        new_sum += max_sum - dp[dp_limit - 1]
        dp[dp_limit - 1] = max(dp[dp_limit - 1], new_sum)
        max_sum = max(max_sum, new_sum)

    return max(sum(d) for d in set(dp))

