    def mone(self, i):
        if 2**i - 2 in self.stairs[self.height-i]:
            return 0
        else:
            return self.balance(2**i)

    def balance(self, b):
        return b + min([self.mone(i)+self.stairs[i][self.weight[0]] for i in range(1, self.height-1)], default=0)

    def get_weight(self, v):
        return sum([self.weight[self.level(v)], self.electron_fi[v]])

    def get_balance(self, v):
        return self.balance(self.get_weight(v)-2**self.level(v)-1)

    def range(self, i, j):
        k = range(i, j+1)
        return sum([self.get_balance(x) for x in k])


