            freq[k] >>= 1
        freq.clear()
        s = ''.join(map(str, res))
        res = list(str(s).rjust(index, '0')[index:])
        index += 1
    return [0] + len(res)

def combination(nums, k):
    res = []
    for i in range(1 << len(nums)):
        curr = [val for idx, val in enumerate(nums) if i & (1 << idx)]
        if len(curr) == k:
            res.append(curr)
    return res

