def find_fair_set(n, k, values):
    # Initialize a dictionary to store the gcd of elements in a given set
    gcd_sets = {tuple(sorted(set(values[i:]))): values[i] for i in range(n)}

    # Sort values to efficiently find common divisors
    values.sort()

    def is_all_fair(values, common_value):
        # Check if all elements in the sorted list share a common value
        return all(gcd_values % common_value == 0 for gcd_values in values)

    for r in range(k, 0, -1):
        all_fair = is_all_fair(values, values[r-1])
        if all_fair:
            return [i+1 for (i, v) in enumerate(values, 1) if v in gcd_sets]

    return [-1]  # In case no fair set is found

