import math

def find_fair_set(n, k, a):
    n *= 2
    dp = [False] * n
    for i in range(n):
        dp[i] = [i]

    for i in range(n, 2*n):
        for j in range(i // 2):
            if a[i % n] == a[j % n]:
                continue
            if math.gcd(a[i % n], a[j % n]) > 1:
                dp[i % n].extend(dp[j % n])
                for val in dp[j % n]:
                    dp[i % n].remove(val)

    result = []
    for i in range(k):
        result.append(dp[i % n].pop())

    return result

