from typing import List

def min_modifications(nums: List[int]) -> int:
    """
    Finds the minimum number of modifications required to partition the given array into permutations.

    :param nums: List[int] - The input array of integers.
    :return: int - The minimum number of modifications required.
    """
    def count_overlaps(nums):
        """Counts the number of elements that overlap more than once in the array."""
        count, overlap, seen = 0, 0, {}
        for num in nums:
            # Count the number of times num appears
            count += nums.count(num)
            # Count the number of times num overlaps with seen numbers
            if num in seen:
                overlap += seen[num]
            # Add the current number's count to seen for future checks
            seen[num] = count
        return count - overlap

    def apply_modification(nums):
        """Attempts a single modification (removing one element).

        :param nums: List[int] - The array to modify.
        :return: bool - True if modification is successful, False otherwise.
        """
        for i, num in enumerate(nums):
            nums.pop(i)
            if len(nums) == 0:
                return True
            if any(num * 2 == o for o in nums):
                return True
            nums.append(num)
        return False

    def xor_transform(arr):
        """XOR-transforms the array to find out if removing an element could make it a permutation."""
        xor_product = reduce(lambda x, y: x ^ y, arr)
        if xor_product == 0:
            return True
        return False

    n = len(nums)
    if n < 2:
        return 0
    overlaps_count = count_overlaps(nums)
    prev_overlaps = overlaps_count
    for i in range(n):
        XOR = nums[i]
        if XOR_transform(nums):
            break
        for j in range(i + 1, n):
            XOR = XOR ^ nums[j]
        if XOR == XOR ^ nums[i]:
            return i + 1 + prev_overlaps  # Modify i elements by shifting 0s to the left
        if XOR_count := count_overlaps(nums[:i + 1]) + count_overlaps(nums[i + 1:]):
            break
    return max(int(n * n / 2 - prev_overlaps) + overlaps_count, n)


